regras.b1.01.001:
:root {
  --primary: #10233f;
  --primary-soft: #173c6b;
  --gold: #b88932;
  --page: #eef2f6;
  --surface: #fff;
  --line: #dbe3ee;
  --text: #172033;
  --muted: #667085;
  font-family: "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif;
}

regras.b1.01.003:
body {
  min-width: 320px;
  min-height: 100dvh;
  margin: 0;
  background: var(--page);
  color: var(--text);
}

regras.b1.01.008:
@keyframes fade {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

regras.b1.01.009:
.open-index {
  position: fixed;
  z-index: 20;
  right: 18px;
  bottom: 18px;
  border: 0;
  border-radius: 999px;
  padding: 10px 14px;
  background: rgba(17, 24, 39, 0.82);
  color: #fff;
  font-weight: 800;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.25);
  cursor: pointer;
}

regras.b1.01.010:
.open-index span {
  display: inline-grid;
  min-width: 18px;
  place-items: center;
  border-radius: 50%;
  background: #fff;
  color: var(--primary);
  font-size: 11px;
}

regras.b1.01.011:
.sheet {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: none;
}

regras.b1.01.014:
.sheet-panel {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  max-height: 72dvh;
  overflow: auto;
  border-radius: 20px 20px 0 0;
  background: #fff;
  box-shadow: 0 -12px 30px rgba(0, 0, 0, 0.2);
}

regras.b1.01.015:
.sheet-head {
  position: sticky;
  top: 0;
  display: flex;
  justify-content: space-between;
  padding: 16px 18px;
  border-bottom: 1px solid var(--line);
  background: #fff;
}

regras.b1.01.016:
.sheet-head button {
  border: 0;
  background: transparent;
  color: var(--primary);
  font-weight: 800;
  cursor: pointer;
}

regras.b1.01.017:
.screen-link {
  display: flex;
  width: 100%;
  gap: 12px;
  align-items: center;
  border: 0;
  border-bottom: 1px solid var(--line);
  padding: 15px 18px;
  background: #fff;
  text-align: left;
  color: var(--text);
  cursor: pointer;
}

regras.b1.01.019:
.screen-link .number {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 50%;
  background: #e8eef5;
  color: var(--primary);
  font-size: 11px;
  font-weight: 900;
}

regras.b1.01.021:
.mark {
  display: grid;
  width: 76px;
  height: 76px;
  margin: auto;
  place-items: center;
  border-radius: 24px;
  background: var(--primary);
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.18);
}

regras.b1.01.023:
.splash {
  display: grid;
  width: 100%;
  min-height: 100dvh;
  padding: 28px;
  place-items: center;
  color: #fff;
  background: radial-gradient(
    circle at 50% 20%,
    #284e7d 0,
    var(--primary) 48%,
    #08172d 100%
  );
}

regras.b1.01.025:
.splash button {
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  text-align: center;
}

regras.b1.01.026:
.splash h1 {
  margin: 22px 0 0;
  font-size: clamp(30px, 8vw, 46px);
  line-height: 1;
  letter-spacing: -0.04em;
}

regras.b1.01.027:
.welcome {
  display: flex;
  flex-direction: column;
  background: var(--surface);
}

regras.b1.01.029:
.welcome__image img {
  display: block;
  width: 100%;
  min-height: 38dvh;
  height: 100%;
  object-fit: cover;
  object-position: top center;
}

regras.b1.01.030:
.welcome__copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  padding: 30px 24px 26px;
}

regras.b1.01.031:
.eyebrow {
  margin: 0 0 10px;
  color: var(--gold);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

regras.b1.01.032:
.welcome h1 {
  margin: 0;
  color: var(--primary);
  font-size: clamp(28px, 7vw, 46px);
  line-height: 1.08;
  letter-spacing: -0.035em;
}

regras.b1.01.035:
.button {
  display: grid;
  width: 100%;
  min-height: 54px;
  place-items: center;
  border: 0;
  border-radius: 13px;
  padding: 14px 18px;
  background: var(--primary);
  color: #fff;
  font-size: 14px;
  font-weight: 800;
  cursor: pointer;
}

regras.b1.01.037:
.topbar {
  min-height: 64px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 18px;
  color: #fff;
  background: var(--primary);
  font-weight: 800;
}

regras.b1.01.038:
.topbar img {
  width: 26px;
  height: 26px;
  object-fit: contain;
  filter: brightness(0) invert(1);
}

regras.b1.01.044:
.card {
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: #fff;
}

regras.b1.01.046:
.field input {
  width: 100%;
  min-height: 57px;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 22px 14px 9px;
  outline: 0;
}

regras.b1.01.047:
.field label {
  position: absolute;
  top: 8px;
  left: 14px;
  color: var(--primary);
  font-size: 10px;
  font-weight: 800;
}

regras.b1.01.048:
.help {
  display: inline-block;
  margin: 2px 0 14px;
  color: var(--primary);
  font-size: 13px;
  font-weight: 800;
}

regras.b1.01.049:
.divider {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 20px 0 12px;
  color: var(--muted);
  font-size: 12px;
}

regras.b1.01.051:
.secondary {
  width: 100%;
  min-height: 50px;
  margin-top: 9px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fff;
  color: var(--primary);
  font-weight: 800;
}

regras.b1.01.052:
.signup {
  margin: 20px 0 0;
  color: var(--muted);
  text-align: center;
  font-size: 13px;
}

regras.b1.01.054:
.status {
  min-height: 20px;
  margin: 12px 0 0;
  color: var(--primary);
  text-align: center;
  font-size: 12px;
  font-weight: 700;
}

regras.b1.01.055:
@media (min-width: 700px) {
  .welcome {
    min-height: 100dvh;
    padding: 34px;
    background: #e9eff6;
  }
  .welcome__layout {
    width: min(1080px, 100%);
    min-height: min(680px, calc(100dvh - 68px));
    margin: auto;
    display: grid;
    grid-template-columns: 1.08fr 0.92fr;
    overflow: hidden;
    border: 1px solid var(--line);
    border-radius: 20px;
    background: #fff;
    box-shadow: 0 12px 36px rgba(16, 35, 63, 0.14);
  }
  .welcome__image,
  .welcome__image img {
    min-height: 0;
    height: 100%;
  }
  .welcome__copy {
    padding: clamp(42px, 6vw, 76px);
  }
  .login__shell {
    padding-top: 54px;
  }
  .card {
    padding: 28px;
    box-shadow: 0 12px 36px rgba(16, 35, 63, 0.14);
  }
}

regras.b1.01.057:
.screen-meta {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

regras.b1.01.063:
.registration__intro h1,
.registration--success h1 {
  margin: 0;
  color: var(--primary);
  font-size: clamp(25px, 7vw, 34px);
  line-height: 1.12;
  letter-spacing: -0.025em;
}

regras.b1.01.064:
.registration__intro > p:not(.eyebrow),
.registration--success > .registration__shell > p:not(.eyebrow):not(.form-status) {
  margin: 10px 0 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.58;
}

regras.b1.01.065:
.progress {
  height: 5px;
  margin: 0 2px 18px;
  overflow: hidden;
  border-radius: 999px;
  background: #dce4ed;
}

regras.b1.01.066:
.progress span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--gold);
}

regras.b1.01.067:
.form-card {
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--surface);
}

regras.b1.01.071:
.select-field label {
  position: absolute;
  z-index: 1;
  top: 8px;
  left: 14px;
  color: var(--primary);
  font-size: 10px;
  font-weight: 800;
  pointer-events: none;
}

regras.b1.01.072:
.select-field select {
  width: 100%;
  min-height: 57px;
  appearance: auto;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 22px 40px 9px 14px;
  outline: 0;
  cursor: pointer;
}

regras.b1.01.074:
.choice-group {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  border: 0;
}

regras.b1.01.075:
.choice-group legend {
  margin-bottom: 10px;
  color: var(--primary);
  font-size: 12px;
  font-weight: 800;
}

regras.b1.01.076:
.choice-card {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 12px;
  align-items: center;
  min-height: 78px;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 14px;
  cursor: pointer;
  transition: border-color .18s ease, background .18s ease, box-shadow .18s ease;
}

regras.b1.01.077:
.choice-card:has(input:checked) {
  border-color: var(--primary-soft);
  background: #f3f7fc;
  box-shadow: inset 0 0 0 1px rgba(23, 60, 107, .16);
}

regras.b1.01.082:
.choice-card small {
  margin-top: 4px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

regras.b1.01.084:
.form-note {
  display: flex;
  gap: 8px;
  margin: 16px 0 0;
  border-radius: 12px;
  padding: 12px 13px;
  background: #f3f6fa;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

regras.b1.01.086:
.form-actions {
  display: grid;
  grid-template-columns: minmax(96px, .7fr) 1.3fr;
  gap: 10px;
  margin-top: 20px;
}

regras.b1.01.088:
.secondary-action {
  min-height: 54px;
  border: 1px solid var(--line);
  border-radius: 13px;
  padding: 14px 16px;
  background: #fff;
  color: var(--primary);
  font-weight: 800;
  cursor: pointer;
}

regras.b1.01.089:
.form-status {
  min-height: 18px;
  margin: 10px 0 0;
  color: #9b2c2c;
  text-align: center;
  font-size: 11px;
  font-weight: 700;
}

regras.b1.01.090:
.upload-field {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px 12px;
  align-items: center;
  margin: 4px 0 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 13px 14px;
  cursor: pointer;
}

regras.b1.01.091:
.upload-field input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

regras.b1.01.094:
.upload-field small,
.upload-field em {
  color: var(--muted);
  font-size: 10px;
  font-style: normal;
}

regras.b1.01.095:
.upload-field em {
  grid-column: 1 / -1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

regras.b1.01.096:
.upload-button {
  border-radius: 9px;
  padding: 9px 10px;
  background: #eef3f8;
  color: var(--primary);
  font-size: 11px;
  font-weight: 800;
}

regras.b1.01.098:
.legal-link {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 13px 14px;
  background: #fff;
  color: var(--primary);
  text-align: left;
  cursor: pointer;
}

regras.b1.01.100:
.legal-link small {
  margin-top: 3px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 500;
}

regras.b1.01.102:
.check-row {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 10px;
  align-items: start;
  color: var(--text);
  font-size: 12px;
  line-height: 1.5;
  cursor: pointer;
}

regras.b1.01.103:
.check-row input {
  width: 18px;
  height: 18px;
  margin: 1px 0 0;
  accent-color: var(--primary);
}

regras.b1.01.104:
.link-button {
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--primary);
  font-weight: 800;
  cursor: pointer;
}

regras.b1.01.106:
.review-section__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

regras.b1.01.108:
.review-section__head button {
  border: 0;
  padding: 5px 0;
  background: transparent;
  color: var(--primary-soft);
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}

regras.b1.01.110:
.review-section dl > div {
  display: grid;
  grid-template-columns: minmax(92px, .55fr) 1.45fr;
  gap: 10px;
  padding: 8px 0;
}

regras.b1.01.112:
.review-section dd {
  margin: 0;
  overflow-wrap: anywhere;
  color: var(--text);
  font-size: 12px;
  font-weight: 700;
}

regras.b1.01.113:
.registration--success .success-shell {
  min-height: calc(100dvh - 64px);
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-top: 36px;
  padding-bottom: 60px;
  text-align: center;
}

regras.b1.01.114:
.success-mark {
  display: grid;
  width: 74px;
  height: 74px;
  margin: 0 auto 18px;
  place-items: center;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  font-size: 34px;
  font-weight: 800;
  box-shadow: 0 12px 28px rgba(16, 35, 63, .18);
}

regras.b1.01.116:
.text-action {
  margin-top: 12px;
  border: 0;
  background: transparent;
  color: var(--primary);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}

regras.b1.01.146:
.app-header {
  position: sticky;
  top: 0;
  z-index: 12;
  min-height: 62px;
  display: grid;
  grid-template-columns: 42px 1fr auto;
  gap: 10px;
  align-items: center;
  padding: 8px 14px;
  background: var(--primary);
  color: #fff;
  box-shadow: 0 4px 14px rgba(16,35,63,.18);
}

regras.b1.01.147:
.app-menu-button {
  width: 40px;
  height: 40px;
  display: grid;
  place-content: center;
  gap: 4px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #fff;
  cursor: pointer;
}

regras.b1.01.148:
.app-menu-button span {
  width: 20px;
  height: 2px;
  border-radius: 9px;
  background: currentColor;
}

regras.b1.01.149:
.app-brand {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 16px;
  letter-spacing: -.02em;
}

regras.b1.01.150:
.app-brand img {
  width: 27px;
  height: 27px;
  object-fit: contain;
  filter: brightness(0) invert(1);
}

regras.b1.01.151:
.app-role {
  font-size: 10px;
  font-weight: 800;
  opacity: .8;
  text-transform: uppercase;
  letter-spacing: .06em;
}

regras.b1.01.152:
.app-titlebar {
  padding: 10px 18px;
  border-bottom: 1px solid var(--line);
  background: #fff;
  color: var(--primary);
  font-size: 13px;
}

regras.b1.01.156:
.op-hero {
  margin-bottom: 14px;
  padding: 19px;
  border-radius: 18px;
  background: linear-gradient(135deg, var(--primary), var(--primary-soft));
  color: #fff;
}

regras.b1.01.159:
.op-card {
  margin-bottom: 12px;
  padding: 17px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: #fff;
}

regras.b1.01.163:
.op-card p {
  margin: 7px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

regras.b1.01.165:
.op-action {
  width: 100%;
  min-height: 78px;
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 15px;
  padding: 14px 15px;
  background: #fff;
  color: var(--text);
  text-align: left;
  cursor: pointer;
}

regras.b1.01.170:
.online-card {
  display: flex;
  gap: 12px;
  align-items: center;
  border-color: #a8dfc8;
  background: #f1fbf6;
}

regras.b1.01.172:
.online-dot {
  width: 9px;
  height: 9px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #15945e;
  box-shadow: 0 0 0 4px rgba(21,148,94,.12);
}

regras.b1.01.174:
.status-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  border-radius: 999px;
  padding: 6px 9px;
  background: #edf3fa;
  color: var(--primary);
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
}

regras.b1.01.178:
.op-tabs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
  margin-bottom: 12px;
}

regras.b1.01.179:
.op-tabs button {
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fff;
  color: var(--muted);
  font-weight: 800;
  cursor: pointer;
}

regras.b1.01.180:
.op-tabs button.active {
  border-color: var(--primary);
  background: var(--primary);
  color: #fff;
}

regras.b1.01.182:
.meta-row {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding-top: 9px;
  border-top: 1px solid #edf0f4;
  font-size: 12px;
}

regras.b1.01.187:
.op-secondary, .op-danger {
  min-height: 48px;
  border-radius: 12px;
  padding: 12px 14px;
  font-weight: 800;
  cursor: pointer;
}

regras.b1.01.188:
.op-secondary {
  border: 1px solid var(--line);
  background: #fff;
  color: var(--primary);
}

regras.b1.01.190:
.op-empty {
  padding: 28px 16px;
  border: 1px dashed #cbd5e1;
  border-radius: 14px;
  background: #f8fafc;
  color: var(--muted);
  text-align: center;
  font-size: 13px;
}

regras.b1.01.192:
.op-form label {
  display: grid;
  gap: 6px;
  color: var(--primary);
  font-size: 11px;
  font-weight: 800;
}

regras.b1.01.193:
.op-form input, .op-form select, .op-form textarea {
  width: 100%;
  min-height: 48px;
  border: 1px solid var(--line);
  border-radius: 11px;
  padding: 11px 12px;
  background: #fff;
  color: var(--text);
  font: inherit;
}

regras.b1.01.195:
.switch-row {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
  padding: 13px 0;
  border-bottom: 1px solid #edf0f4;
}

regras.b1.01.199:
.prototype-switch {
  position: relative;
  width: 46px;
  height: 26px;
  flex: 0 0 auto;
  border: 0;
  border-radius: 999px;
  background: #15945e;
  cursor: pointer;
}

regras.b1.01.200:
.prototype-switch::after {
  position: absolute;
  top: 3px;
  right: 3px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #fff;
  content: "";
  box-shadow: 0 2px 5px rgba(0,0,0,.18);
}

regras.b1.01.204:
.day-list label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 49px;
  border: 1px solid var(--line);
  border-radius: 11px;
  padding: 10px 12px;
  background: #fff;
  color: var(--primary);
  font-weight: 800;
}

regras.b1.01.206:
.radius-value {
  margin: 4px 0 14px;
  color: var(--primary);
  text-align: center;
  font-size: 38px;
  font-weight: 900;
}

regras.b1.01.209:
.profile-avatar {
  width: 58px;
  height: 58px;
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 18px;
  background: #dfe8f3;
  color: var(--primary);
  font-weight: 900;
}

regras.b1.01.210:
.bottom-nav {
  position: fixed;
  z-index: 10;
  right: 0;
  bottom: 0;
  left: 0;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  border-top: 1px solid var(--line);
  background: rgba(255,255,255,.97);
  backdrop-filter: blur(12px);
}

regras.b1.01.211:
.bottom-nav button {
  min-height: 64px;
  border: 0;
  padding: 7px 3px;
  background: transparent;
  color: #778195;
  font-size: 9px;
  font-weight: 800;
  cursor: pointer;
}

regras.b1.01.213:
.prototype-drawer {
  position: fixed;
  z-index: 40;
  inset: 0;
  display: none;
}

regras.b1.01.215:
.drawer-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  border: 0;
  background: rgba(7,16,30,.55);
}

regras.b1.01.216:
.drawer-panel {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: min(88vw, 360px);
  overflow: auto;
  padding: 18px 14px 22px;
  background: linear-gradient(180deg, #10233f, #0a1b32);
  color: #fff;
  box-shadow: 12px 0 28px rgba(0,0,0,.28);
}

regras.b1.01.217:
.drawer-top {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: flex-start;
  padding: 8px 5px 18px;
}

regras.b1.01.220:
.drawer-identity small {
  margin-top: 3px;
  color: #aebdd0;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .08em;
}

regras.b1.01.221:
.drawer-avatar {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border: 1px solid #ffffff33;
  border-radius: 50%;
  background: #ffffff14;
  font-weight: 900;
}

regras.b1.01.222:
.drawer-close {
  border: 0;
  background: transparent;
  color: #fff;
  font-size: 30px;
  line-height: 1;
  cursor: pointer;
}

regras.b1.01.223:
.drawer-online {
  width: 100%;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;
  border: 1px solid #ffffff1f;
  border-radius: 13px;
  padding: 12px;
  background: #ffffff0d;
  color: #fff;
  text-align: left;
  cursor: pointer;
}

regras.b1.01.226:
.online-switch {
  position: relative;
  width: 42px;
  height: 24px;
  border-radius: 999px;
  background: #15945e;
}

regras.b1.01.227:
.online-switch b {
  position: absolute;
  top: 3px;
  right: 3px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #fff;
}

regras.b1.01.231:
.drawer-nav button, .drawer-footer button {
  min-height: 44px;
  border: 0;
  border-radius: 10px;
  padding: 10px 12px;
  background: transparent;
  color: #f8fafc;
  text-align: left;
  font-weight: 700;
  cursor: pointer;
}

regras.b1.01.235:
.op-toast {
  position: fixed;
  z-index: 50;
  left: 50%;
  bottom: 82px;
  max-width: calc(100vw - 32px);
  transform: translate(-50%, 16px);
  border-radius: 999px;
  padding: 10px 14px;
  background: #111827;
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  opacity: 0;
  pointer-events: none;
  transition: .2s ease;
}

regras.b1.01.238:
@media (min-width: 720px) {
  .op-shell { padding: 28px 22px 52px; }
  .op-grid.two { grid-template-columns: 1fr 1fr; }
  .bottom-nav {
    left: 50%;
    width: min(720px, 100%);
    transform: translateX(-50%);
    border-right: 1px solid var(--line);
    border-left: 1px solid var(--line);
    border-radius: 16px 16px 0 0;
    overflow: hidden;
  }
}

regras.b1.01.241:
.client-legacy .op-card,
.client-legacy .op-action {
  border: 1px solid var(--client-line);
  border-radius: 14px;
  background: var(--client-surface);
  box-shadow: 0 4px 12px rgba(15, 23, 42, .035);
}

regras.b1.01.243:
.client-legacy .op-action {
  width: 100%;
  min-height: 72px;
  margin: 0 0 12px;
  padding: 14px 16px;
  color: var(--client-text);
  text-align: left;
}

regras.b1.01.245:
.client-legacy .op-action strong {
  margin-bottom: 4px;
  color: var(--client-text);
  font-size: 15px;
  font-weight: 800;
}

regras.b1.01.246:
.client-legacy .op-action small {
  color: var(--client-muted);
  font-size: 12px;
  line-height: 1.4;
  font-weight: 600;
}

regras.b1.01.248:
.client-home-head h1 {
  margin: 0 0 8px;
  color: var(--client-primary);
  font-size: 24px;
  line-height: 1.15;
}

regras.b1.01.249:
.client-home-head p {
  margin: 0;
  color: var(--client-muted);
  font-size: 14px;
  line-height: 1.5;
}

regras.b1.01.250:
.client-home-action {
  width: 100%;
  display: grid;
  grid-template-columns: 44px 1fr auto;
  gap: 12px;
  align-items: center;
  margin-bottom: 12px;
  padding: 16px;
  border: 1px solid var(--client-line);
  border-radius: 14px;
  background: var(--client-surface);
  color: var(--client-text);
  text-align: left;
  box-shadow: 0 4px 12px rgba(15, 23, 42, .035);
  cursor: pointer;
}

regras.b1.01.251:
.client-home-action .iconbox {
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border-radius: 13px;
  background: #e7f0ff;
  color: var(--client-primary);
  font-weight: 900;
}

regras.b1.01.255:
.client-home-action .txt small {
  color: var(--client-muted);
  font-size: 12px;
  line-height: 1.4;
  font-weight: 600;
}

regras.b1.01.257:
.client-notice {
  margin-top: 12px;
  padding: 13px 14px;
  border: 1px solid #ead6a9;
  border-radius: 12px;
  background: #fff8e8;
  color: #70510b;
  font-size: 12px;
  line-height: 1.45;
}

regras.b1.01.258:
.client-map {
  position: relative;
  min-height: 210px;
  overflow: hidden;
  margin-bottom: 14px;
  border: 1px solid var(--client-line, #dbe3ee);
  border-radius: 14px;
  background:
    linear-gradient(90deg, rgba(16,35,63,.06) 1px, transparent 1px) 0 0/36px 36px,
    linear-gradient(rgba(16,35,63,.06) 1px, transparent 1px) 0 0/36px 36px,
    #eaf0f6;
}

regras.b1.01.259:
.client-map::before,
.client-map::after {
  position: absolute;
  width: 18px;
  height: 18px;
  border-radius: 50% 50% 50% 0;
  background: #10233f;
  box-shadow: 0 4px 10px rgba(16,35,63,.2);
  content: "";
  transform: rotate(-45deg);
}

regras.b1.01.262:
.client-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 12px 0;
}

regras.b1.01.263:
.client-chip {
  border: 1px solid #dbe3ee;
  border-radius: 999px;
  padding: 8px 11px;
  background: #fff;
  color: #10233f;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}

regras.b1.01.266:
.client-step {
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 10px;
  align-items: center;
  color: #667085;
  font-size: 12px;
}

regras.b1.01.267:
.client-step span:first-child {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 50%;
  background: #e7edf4;
  color: #10233f;
  font-size: 10px;
  font-weight: 900;
}

regras.b1.01.269:
.client-profile {
  display: grid;
  grid-template-columns: 48px 1fr auto;
  gap: 12px;
  align-items: center;
}

regras.b1.01.270:
.client-avatar {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border-radius: 13px;
  background: #e7f0ff;
  color: #10233f;
  font-weight: 900;
}

regras.b1.01.272:
.login-flow__bar {
  min-height: calc(64px + env(safe-area-inset-top));
  padding-top: env(safe-area-inset-top);
  padding-left: max(18px, env(safe-area-inset-left));
  padding-right: max(18px, env(safe-area-inset-right));
  display: flex;
  align-items: center;
  gap: 10px;
  background: #10233f;
  color: #fff;
  font-size: 16px;
  font-weight: 800;
}

regras.b1.01.274:
.login-flow__content {
  width: min(calc(100% - 40px), var(--login-flow-content-max));
  margin-inline: auto;
  padding: 20px 0 32px;
}

regras.b1.01.277:
.login-flow .role-choice {
  margin-bottom: 12px;
  padding: 14px;
  border: 1px solid #dbe3ee;
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 4px 12px rgba(15,23,42,.035);
}

regras.b1.01.278:
.login-flow .role-choice-head {
  display: grid;
  grid-template-columns: 44px 1fr;
  gap: 12px;
  align-items: center;
  margin-bottom: 12px;
}

regras.b1.01.279:
.login-flow .mini-icon {
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border-radius: 13px;
  background: #e7f0ff;
  color: #10233f;
  font-weight: 900;
}

regras.b1.01.284:
.login-flow .role-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

regras.b1.01.286:
.login-flow .role-actions button {
  min-height: 38px;
  border: 1px solid #10233f;
  border-radius: 10px;
  padding: 8px 10px;
  background: #10233f;
  color: #fff;
  font: inherit;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: .03em;
  cursor: pointer;
}

regras.b1.01.289:
.login-flow__note {
  margin-top: 16px;
  padding: 12px 13px;
  border: 1px dashed #c8d3df;
  border-radius: 12px;
  color: #667085;
  font-size: 11px;
  line-height: 1.45;
}

regras.b1.02.001:
:host {
  display: block;
  width: 100%;
  color: var(--text, #172033);
  font-family: "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif;
}

